// Pause menu: RmlUi document drawn into ImGui's foreground draw list, so it reaches the screen through the same
// presenter pass as the debug panel (Vulkan swapchain or SDL_Renderer). Main thread only, except the EE-side wait.

#include "ps2_menu.h"
#include "ps2_menu_host.h"
#include "ps2_host_sdl.h"
#include "ps2_input.h"
#include "ps2_user_config.h"
#include "ps2_fmv.h"
#include "ps2_menu_font.h" // kPs2xMenuFont (Roboto Medium), generated by CMake

#include <RmlUi/Core.h>

#include "imgui.h"
#include "imgui_internal.h" // RegisterUserTexture, ImDrawListSharedData

#include <algorithm>
#include <atomic>
